-- Navigation is independent of content type. One page may belong to several sections.
create table public.foamlab_sections (
 id uuid primary key default gen_random_uuid(),
 key text not null unique default gen_random_uuid()::text,
 name text not null check (char_length(trim(name)) between 1 and 60),
 parent_id uuid references public.foamlab_sections(id) on delete restrict,
 href text not null default '' check (href='' or (href ~ '^/[^/]' and href !~ '[\\]' ) or href='/'),
 description text not null default '' check(char_length(description)<=1000),
 nav_group text not null default '学习空间',
 visible boolean not null default true,
 sort_order integer not null default 0,
 revision integer not null default 1,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index foamlab_sections_parent_idx on public.foamlab_sections(parent_id);
alter table public.foamlab_sections enable row level security;
revoke all on public.foamlab_sections from public,anon,authenticated;
grant select on public.foamlab_sections to anon,authenticated;
grant insert,update,delete on public.foamlab_sections to authenticated;
create policy sections_read on public.foamlab_sections for select using(true);
create policy sections_insert on public.foamlab_sections for insert to authenticated with check(foamlab_private.has_role(array['admin','editor']));
create policy sections_update on public.foamlab_sections for update to authenticated using(foamlab_private.has_role(array['admin','editor'])) with check(foamlab_private.has_role(array['admin','editor']));
create policy sections_delete on public.foamlab_sections for delete to authenticated using(foamlab_private.has_role(array['admin','editor']));
alter table public.foamlab_content add column section_ids uuid[] not null default '{}';
create index foamlab_content_sections_idx on public.foamlab_content using gin(section_ids);
