alter table public.foamlab_content enable trigger save_content_revision;
alter table public.foamlab_content enable trigger pet_article_award;

-- Serialize topology changes and placement writes to prevent cycles and dangling IDs.
create function foamlab_private.section_guard() returns trigger language plpgsql set search_path='' as $$
declare seen uuid[]; cursor_id uuid;
begin
 perform pg_advisory_xact_lock(7402512);
 if tg_op='DELETE' then
  if exists(select 1 from public.foamlab_content where old.id=any(section_ids)) then
   raise exception '请先移走此目录的内容，或使用目录删除功能。';
  end if;
  return old;
 end if;
 seen:=array[new.id]; cursor_id:=new.parent_id;
 while cursor_id is not null loop
  if cursor_id=any(seen) then raise exception '上级目录应在当前目录及其子目录之外。'; end if;
  seen:=array_append(seen,cursor_id);
  select parent_id into cursor_id from public.foamlab_sections where id=cursor_id;
 end loop;
 if tg_op='UPDATE' then new.revision:=old.revision+1; new.updated_at:=now(); new.key:=old.key; end if;
 return new;
end $$;
revoke all on function foamlab_private.section_guard() from public,anon,authenticated;
create trigger section_guard before insert or update or delete on public.foamlab_sections for each row execute function foamlab_private.section_guard();

create function foamlab_private.content_sections_guard() returns trigger language plpgsql set search_path='' as $$
declare community_id uuid;
begin
 -- Ordinary edits do not rewrite an admin's placements on a member's own article.
 if tg_op='UPDATE' and new.section_ids is not distinct from old.section_ids then return new; end if;
 perform pg_advisory_xact_lock(7402512);
 if tg_op='INSERT' and cardinality(new.section_ids)=0 and new.kind in ('article','log') and coalesce(new.metadata->>'admin_only','false')<>'true' then
  select id into community_id from public.foamlab_sections where key='sharing';
  if community_id is not null then new.section_ids:=array[community_id]; end if;
 end if;
 if cardinality(new.section_ids)>20 then raise exception '每篇内容最多选择 20 个位置。'; end if;
 if exists(select 1 from unnest(new.section_ids) s(id) where id is null or not exists(select 1 from public.foamlab_sections d where d.id=s.id)) then raise exception '目录已变化，请刷新后重新选择位置。'; end if;
 select coalesce(array_agg(distinct x),'{}'::uuid[]) into new.section_ids from unnest(new.section_ids) x;
 if current_user in ('anon','authenticated') and not foamlab_private.has_role(array['admin','editor']) then
  if tg_op='UPDATE' then raise exception '文章位置由管理员调整。'; end if;
  if exists(select 1 from public.foamlab_sections where id=any(new.section_ids) and key<>'sharing') then raise exception '个人文章发布在实践与分享。'; end if;
 end if;
 return new;
end $$;
revoke all on function foamlab_private.content_sections_guard() from public,anon,authenticated;
create trigger a_content_sections_guard before insert or update on public.foamlab_content for each row execute function foamlab_private.content_sections_guard();

-- Removing a directory only removes placement links. Articles, attachments and URLs survive.
create function public.foamlab_delete_section(section_id uuid, expected_revision integer) returns integer
language plpgsql security invoker set search_path='' as $$
declare ids uuid[]; removed integer; child record;
begin
 if not foamlab_private.has_role(array['admin','editor']) then raise exception '需要内容管理权限。'; end if;
 perform pg_advisory_xact_lock(7402512);
 if not exists(select 1 from public.foamlab_sections where id=section_id and revision=expected_revision) then raise exception '目录已被更新，请刷新后重试。'; end if;
 with recursive tree as (select id from public.foamlab_sections where id=section_id union all select s.id from public.foamlab_sections s join tree t on s.parent_id=t.id) select array_agg(id) into ids from tree;
 update public.foamlab_content c set section_ids=array(select x from unnest(c.section_ids) x where not(x=any(ids))) where c.section_ids && ids;
 get diagnostics removed=row_count;
 -- Delete leaves first because the parent foreign key is restrictive.
 for child in with recursive tree as (select id,0 depth from public.foamlab_sections where id=section_id union all select s.id,t.depth+1 from public.foamlab_sections s join tree t on s.parent_id=t.id) select id from tree order by depth desc loop
  delete from public.foamlab_sections where id=child.id;
 end loop;
 return removed;
end $$;
revoke all on function public.foamlab_delete_section(uuid,integer) from public,anon,authenticated;
grant execute on function public.foamlab_delete_section(uuid,integer) to authenticated;
